# devflow project launcher for Windows (generated by `devflow init`; commit it).
# Runs the installed devflow, or bootstraps the latest stable release on first use.
$ErrorActionPreference = 'Stop'

$cacheRoot = if ($env:LOCALAPPDATA) { Join-Path $env:LOCALAPPDATA 'devflow' } else { Join-Path $HOME '.cache\devflow' }
$pointer = Join-Path $cacheRoot 'current.txt'
if (Test-Path $pointer) {
  $exe = Join-Path (Get-Content $pointer -Raw).Trim() 'devflow.exe'
  if (Test-Path $exe) { & $exe @args; exit $LASTEXITCODE }
}

if (-not (Get-Command gh -ErrorAction SilentlyContinue)) {
  [Console]::Error.WriteLine('devflow: first run needs the GitHub CLI (gh) logged in to github.com')
  exit 1
}

$arch = if ([Environment]::Is64BitOperatingSystem) { 'amd64' } else { throw 'devflow: unsupported architecture' }
$tag = (gh release view --repo nscaledev/devflow --json tagName -q .tagName).Trim()
$ver = $tag.TrimStart('v')
$pkg = "devflow_${ver}_windows_${arch}.zip"
$tmp = Join-Path ([IO.Path]::GetTempPath()) ([IO.Path]::GetRandomFileName())
New-Item -ItemType Directory -Path $tmp | Out-Null
try {
  [Console]::Error.WriteLine("devflow: first run, installing $tag")
  gh release download $tag --repo nscaledev/devflow --dir $tmp --pattern $pkg --pattern checksums.txt 2>&1 | ForEach-Object { [Console]::Error.WriteLine($_) }

  $want = (Select-String -Path (Join-Path $tmp 'checksums.txt') -Pattern " $([regex]::Escape($pkg))$").Line.Split(' ')[0]
  $got = (Get-FileHash -Algorithm SHA256 (Join-Path $tmp $pkg)).Hash.ToLower()
  if ($want -ne $got) { throw "devflow: checksum mismatch for $pkg, not installing" }

  gh attestation verify (Join-Path $tmp $pkg) --repo nscaledev/devflow 2>&1 | ForEach-Object { [Console]::Error.WriteLine($_) }
  if ($LASTEXITCODE -ne 0) { throw 'devflow: build attestation did not verify, not installing' }

  $dest = Join-Path $cacheRoot $ver
  New-Item -ItemType Directory -Force -Path $dest | Out-Null
  Expand-Archive -Path (Join-Path $tmp $pkg) -DestinationPath $dest -Force
  Set-Content -Path $pointer -Value $dest -NoNewline
} finally {
  Remove-Item -Recurse -Force $tmp -ErrorAction SilentlyContinue
}

& (Join-Path $dest 'devflow.exe') @args
exit $LASTEXITCODE
